Haces **2 clics** en el botón. ¿Qué muestra el párrafo?

```jsx
function reducer(estado, accion) {
  if (accion.tipo === "sumar") {
    estado.cuenta++;
    return estado;
  }
  return estado;
}

function Contador() {
  const [estado, dispatch] = useReducer(reducer, { cuenta: 0 });
  return (
    <>
      <button onClick={() => dispatch({ tipo: "sumar" })}>+</button>
      <p>Cuenta: {estado.cuenta}</p>
    </>
  );
}
```

¿Qué texto se ve en pantalla? (React 19)

