  return <span>{useContext(Tema)} </span>;
}

function App() {
  return (
    <div>
      <Tema value="oscuro">
        <Hijo />
        <Tema value="azul">
          <Hijo />
        </Tema>
      </Tema>
      <Hijo />
    </div>
  );
}
```

