```jsx
function Panel() {
  const [cuenta, setCuenta] = useState(0);

  const mostrar = useCallback(() => {
    console.log(cuenta);
  }, []);

  return (
    <>
      <button onClick={() => setCuenta((c) => c + 1)}>sumar</button>
      <button onClick={mostrar}>mostrar</button>
    </>
  );
}
```

